#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, datetime as _dt, importlib.util, os, py_compile, shutil, subprocess, sys
from pathlib import Path
VERSION='0.1.1'
OLD_B64={'frontend/src/Pages/LabView.tsx': '', 'frontend/src/api/labServiceApi.ts': '', 'frontend/tools/generate_llm_context_map.py': '', 'backend/app/services/vision_labs/service/models.py': '', 'backend/app/services/vision_labs/service/repository.py': '', 'backend/app/services/vision_labs/service/runtime.py': '', 'backend/app/api/v1/endpoints/lab_service_api.py': ''}
NEW_B64={'frontend/src/Pages/LabView.tsx': '', 'frontend/src/api/labServiceApi.ts': '', 'frontend/tools/generate_llm_context_map.py': '', 'backend/app/services/vision_labs/service/models.py': '', 'backend/app/services/vision_labs/service/repository.py': '', 'backend/app/services/vision_labs/service/runtime.py': '', 'backend/app/api/v1/endpoints/lab_service_api.py': ''}
CREATE_B64={'frontend/src/Pages/SamplingGeometryLabPage.tsx': '', 'frontend/src/api/samplingGeometryApi.ts': '', 'frontend/src/components/VisionLabs/SamplingGeometry/SamplingGuideModal.tsx': '', 'frontend/src/components/VisionLabs/SamplingGeometry/SamplingStack.tsx': '', 'frontend/src/components/VisionLabs/SamplingGeometry/SamplingVisuals.tsx': '', 'frontend/src/components/VisionLabs/SamplingGeometry/useSamplingGeometryController.ts': '', 'frontend/src/components/VisionLabs/SamplingGeometry/SamplingWorkbench.tsx': '', 'frontend/src/components/VisionLabs/SamplingGeometry/SamplingOperatorLibrary.tsx': '', 'frontend/src/components/VisionLabs/SamplingGeometry/types.ts': '', 'frontend/docs/llm_context/updates/v0100_sampling_geometry_lab.md': '', 'backend/tests/vision_labs/sampling_geometry/test_sampling_geometry_lab_v0100.py': '', 'backend/app/api/v1/endpoints/sampling_geometry_api.py': '', 'backend/app/services/vision_labs/sampling_geometry/specs.py': '', 'backend/app/services/vision_labs/sampling_geometry/operator.py': '', 'backend/app/services/vision_labs/sampling_geometry/types.py': '', 'backend/app/services/vision_labs/sampling_geometry/serialization.py': '', 'backend/app/services/vision_labs/sampling_geometry/pipeline.py': '', 'backend/app/services/vision_labs/sampling_geometry/__init__.py': '', 'backend/app/services/vision_labs/sampling_geometry/session.py': '', 'backend/app/services/vision_labs/sampling_geometry/repository.py': '', 'backend/app/services/vision_labs/sampling_geometry/runtime.py': '', 'backend/app/services/vision_labs/sampling_geometry/registry.py': '', 'backend/app/services/vision_labs/sampling_geometry/preview.py': '', 'backend/app/services/vision_labs/service/__init__.py': '', 'backend/app/services/vision_labs/sampling_geometry/operators/spectral.py': '', 'backend/app/services/vision_labs/sampling_geometry/operators/geometry.py': '', 'backend/app/services/vision_labs/sampling_geometry/operators/__init__.py': '', 'backend/app/services/vision_labs/sampling_geometry/operators/common.py': '', 'backend/app/services/vision_labs/sampling_geometry/operators/spatial.py': ''}
OLD_FILES={k:base64.b64decode(v).decode('utf-8') for k,v in OLD_B64.items()}
NEW_FILES={k:base64.b64decode(v).decode('utf-8') for k,v in NEW_B64.items()}
CREATE_FILES={k:base64.b64decode(v).decode('utf-8') for k,v in CREATE_B64.items()}
ROUTER_IMPORT='from app.api.v1.endpoints import sampling_geometry_api'
ROUTER_MOUNT='api_router.include_router(sampling_geometry_api.router, prefix="/sampling-geometry", tags=["Sampling / Geometry LAB"])'
APP_IMPORT="import { SamplingGeometryLabPage } from './Pages/SamplingGeometryLabPage';"
APP_ROUTE='<Route path="/labs/sampling-geometry" element={<SamplingGeometryLabPage />} />'

def resolve_roots(frontend_arg,backend_arg):
    cwd=Path.cwd().resolve(); fe=[]; be=[]
    if frontend_arg: fe.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg: be.append(Path(backend_arg).expanduser().resolve())
    fe += [cwd,cwd/'LambdaVisionSuper',cwd.parent/'LambdaVisionSuper']
    be += [cwd,cwd/'LambdaVisionSuperBackEnd',cwd.parent/'LambdaVisionSuperBackEnd']
    frontend=next((p for p in fe if (p/'src/App.tsx').exists() and (p/'src/Pages/LabView.tsx').exists()),None)
    backend=next((p for p in be if (p/'app/api/v1/api.py').exists() and (p/'app/services/vision_labs/image/runtime.py').exists()),None)
    if frontend is None: raise RuntimeError('Cannot locate frontend; use --frontend')
    if backend is None: raise RuntimeError('Cannot locate backend; use --backend')
    return frontend,backend

def actual(frontend,backend,virtual):
    prefix,rel=virtual.split('/',1); return (frontend if prefix=='frontend' else backend)/rel

def state(path,old,new):
    if not path.exists(): return 'MISSING'
    cur=path.read_text(encoding='utf-8')
    return 'OK' if cur==new else 'UPDATE' if cur==old else 'CONFLICT'

def create_state(path,desired):
    if not path.exists(): return 'CREATE'
    return 'OK' if path.read_text(encoding='utf-8')==desired else 'CONFLICT'

def patch_app(text):
    changed=False
    if APP_IMPORT not in text:
        anchor="import { ImageProcessingLabPage } from './Pages/ImageProcessingLabPage';"
        if anchor not in text: raise RuntimeError('Missing ImageProcessingLabPage import anchor')
        text=text.replace(anchor,anchor+'\n'+APP_IMPORT,1); changed=True
    if APP_ROUTE not in text:
        anchor='<Route path="/labs/image-processing" element={<ImageProcessingLabPage />} />'
        if anchor not in text: raise RuntimeError('Missing Image Processing route anchor')
        text=text.replace(anchor,anchor+'\n        '+APP_ROUTE,1); changed=True
    return text,changed

def patch_router(text):
    changed=False
    if ROUTER_IMPORT not in text:
        anchor='from app.api.v1.endpoints import lab_service_api'
        if anchor in text: text=text.replace(anchor,anchor+'\n'+ROUTER_IMPORT,1)
        else:
            lines=text.splitlines(); idx=next((i for i,l in enumerate(lines) if l.startswith('from app.api.v1.endpoints import ')),None)
            if idx is None: raise RuntimeError('Missing backend endpoint import anchor')
            lines.insert(idx+1,ROUTER_IMPORT); text='\n'.join(lines)+('\n' if text.endswith('\n') else '')
        changed=True
    if ROUTER_MOUNT not in text:
        lines=text.splitlines(); idx=None
        for i,l in enumerate(lines):
            if 'api_router.include_router(' in l: idx=i
        if idx is None: raise RuntimeError('Missing backend router include anchor')
        lines.insert(idx+1,ROUTER_MOUNT); text='\n'.join(lines)+('\n' if text.endswith('\n') else ''); changed=True
    return text,changed

def backup(frontend,backend,paths):
    stamp=_dt.datetime.now().strftime('%Y%m%d_%H%M%S'); root=frontend/'.lambda_updater_backups'/f'sampling_geometry_lab_v0100_{stamp}'; root.mkdir(parents=True,exist_ok=True)
    for p in paths:
        if not p.exists(): continue
        try: rel=p.relative_to(frontend); dest=root/'frontend'/rel
        except ValueError: rel=p.relative_to(backend); dest=root/'backend'/rel
        dest.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(p,dest)
    return root

def scan(frontend,backend):
    print('='*92); print('SAMPLING / GEOMETRY LAB V0.1.1'); print('='*92); print('Frontend :',frontend); print('Backend  :',backend); print()
    conflicts=0
    for v,n in NEW_FILES.items():
        st=state(actual(frontend,backend,v),OLD_FILES[v],n); print(f'  [{st:10}] {v}')
        if st in {'CONFLICT','MISSING'} and v!='frontend/tools/generate_llm_context_map.py': conflicts+=1
    for v,d in CREATE_FILES.items():
        st=create_state(actual(frontend,backend,v),d); print(f'  [{st:10}] {v}'); conflicts += 1 if st=='CONFLICT' else 0
    app=(frontend/'src/App.tsx').read_text(encoding='utf-8'); pa,_=patch_app(app); print(f"  [{'OK' if pa==app else 'PATCH':10}] frontend/src/App.tsx")
    rt=(backend/'app/api/v1/api.py').read_text(encoding='utf-8'); pr,_=patch_router(rt); print(f"  [{'OK' if pr==rt else 'PATCH':10}] backend/app/api/v1/api.py")
    print('\nOperator catalog: Geometry=5 · Spatial=4 · Spectral/Statistics=5')
    print('Input: Upload or upstream Image Processing Lab Service output')
    print('Deploy: sampling_geometry service with workspace_type')
    print('Guide: text + interactive model; Workbench: real overlays / FFT / charts')
    if conflicts: print(f'\n[WARN] {conflicts} conflict(s); apply will stop safely.')
    return 0

def preflight(frontend,backend):
    errors=[]
    for v,n in NEW_FILES.items():
        if v=='frontend/tools/generate_llm_context_map.py': continue
        st=state(actual(frontend,backend,v),OLD_FILES[v],n)
        if st not in {'OK','UPDATE'}: errors.append(f'{v}: {st}')
    for v,d in CREATE_FILES.items():
        st=create_state(actual(frontend,backend,v),d)
        if st not in {'OK','CREATE'}: errors.append(f'{v}: {st}')
    patch_app((frontend/'src/App.tsx').read_text(encoding='utf-8')); patch_router((backend/'app/api/v1/api.py').read_text(encoding='utf-8'))
    if errors: raise RuntimeError('Safe update stopped:\n  - '+'\n  - '.join(errors))

def regenerate_context(frontend,backend):
    g=frontend/'tools/generate_llm_context_map.py'
    if not g.exists(): print('[SKIP] Context generator missing'); return
    r=subprocess.run([sys.executable,str(g),'--frontend',str(frontend),'--backend',str(backend),'--output-dir',str(frontend/'docs/llm_context')],cwd=str(frontend),text=True,capture_output=True)
    if r.returncode==0: print('[OK] Regenerated LLM context maps')
    else: print('[WARN] Context regeneration failed'); print((r.stdout+'\n'+r.stderr).strip())

def apply(frontend,backend):
    preflight(frontend,backend)
    paths=[actual(frontend,backend,v) for v in list(NEW_FILES)+list(CREATE_FILES)]+[frontend/'src/App.tsx',backend/'app/api/v1/api.py']; root=backup(frontend,backend,paths)
    for v,n in NEW_FILES.items():
        p=actual(frontend,backend,v)
        if v=='frontend/tools/generate_llm_context_map.py' and state(p,OLD_FILES[v],n)=='CONFLICT': print('[KEEP] Context generator local modifications'); continue
        p.parent.mkdir(parents=True,exist_ok=True)
        if not p.exists() or p.read_text(encoding='utf-8')!=n: p.write_text(n,encoding='utf-8'); print('[WRITE]',v)
    for v,d in CREATE_FILES.items():
        p=actual(frontend,backend,v); p.parent.mkdir(parents=True,exist_ok=True)
        if not p.exists() or p.read_text(encoding='utf-8')!=d: p.write_text(d,encoding='utf-8'); print('[WRITE]',v)
    p=frontend/'src/App.tsx'; t,c=patch_app(p.read_text(encoding='utf-8')); 
    if c: p.write_text(t,encoding='utf-8'); print('[PATCH] frontend/src/App.tsx')
    p=backend/'app/api/v1/api.py'; t,c=patch_router(p.read_text(encoding='utf-8')); 
    if c: p.write_text(t,encoding='utf-8'); print('[PATCH] backend/app/api/v1/api.py')
    regenerate_context(frontend,backend); print('[OK] Backup:',root); print('Run verify next.'); return 0

def ts_check(frontend):
    files=[str(actual(frontend,frontend,v)) for v in CREATE_FILES if v.startswith('frontend/') and v.endswith(('.ts','.tsx'))]+[str(frontend/'src/api/labServiceApi.ts'),str(frontend/'src/Pages/LabView.tsx')]
    code="const fs=require('fs'),ts=require('typescript');let f=false;for(const p of process.argv.slice(1)){const r=ts.transpileModule(fs.readFileSync(p,'utf8'),{fileName:p,reportDiagnostics:true,compilerOptions:{jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.ESNext}}),e=(r.diagnostics||[]).filter(x=>x.category===ts.DiagnosticCategory.Error);if(e.length){f=true;console.error('TS',p);for(const d of e)console.error(ts.flattenDiagnosticMessageText(d.messageText,'\\n'));}}process.exit(f?1:0);"
    env=dict(os.environ); env['NODE_PATH']=subprocess.run(['npm','root','-g'],text=True,capture_output=True).stdout.strip(); return subprocess.run(['node','-e',code,*files],cwd=str(frontend),text=True,capture_output=True,env=env)

def backend_smoke(backend):
    code="""import numpy as np\nfrom datetime import datetime,timezone\nfrom app.services.vision_labs.image.types import ImageFrame,ColorSpace\nfrom app.services.vision_labs.sampling_geometry.operators import load_sampling_geometry_operators\nfrom app.services.vision_labs.sampling_geometry.registry import SAMPLING_OPERATOR_REGISTRY\nfrom app.services.vision_labs.sampling_geometry.pipeline import SamplingPipelineDefinition\nfrom app.services.vision_labs.sampling_geometry.runtime import SamplingGeometryRuntime\nfrom app.services.vision_labs.service.models import LabServiceDefinition,LabServicePort,LabServiceOutputBinding\nfrom app.services.vision_labs.service.runtime import LabServiceRuntime\nload_sampling_geometry_operators(); assert len(SAMPLING_OPERATOR_REGISTRY.manifests())>=14\nimg=np.zeros((96,128,3),np.uint8); img[...,0]=np.arange(128,dtype=np.uint8)[None,:]; img[...,1]=120; img[...,2]=200\np=SamplingPipelineDefinition(workspace='spectral',nodes=[{'id':'fft','operator_id':'sampling.spectral.fft2d','parameters':{'channel':'gray','window':'hann','remove_mean':True}},{'id':'bands','operator_id':'sampling.spectral.radial_bands','parameters':{'bands':8,'normalize':True}}],connections=[{'source':{'node_id':'fft','port':'spectrum'},'target':{'node_id':'bands','port':'spectrum'}}],inputs={'input':{'node_id':'fft','port':'image'}},outputs={'result':{'node_id':'bands','port':'features'}})\nr=SamplingGeometryRuntime(p).run({'input':ImageFrame(img,color_space=ColorSpace.BGR)}); assert r.outputs['result'].shape==(8,)\nnow=datetime.now(timezone.utc).isoformat(); s=LabServiceDefinition(service_id='smoke',name='Smoke',lab_type='sampling_geometry',workspace_type='spectral',version=1,inputs={'input':LabServicePort(type='image')},outputs={'features':LabServiceOutputBinding(type='feature_vector',node_id='bands',port='features')},pipeline_snapshot=p.model_dump() if hasattr(p,'model_dump') else p.dict(),created_at=now,deployed_at=now)\nrun=LabServiceRuntime().run(s,{'input':ImageFrame(img,color_space=ColorSpace.BGR)}); assert run.manifest.outputs['features']['type']=='feature_vector'\nprint('SAMPLING_GEOMETRY_SMOKE_OK',len(SAMPLING_OPERATOR_REGISTRY.manifests()),run.manifest.workspace_type)"""
    return subprocess.run([sys.executable,'-c',code],cwd=str(backend),text=True,capture_output=True)

def verify(frontend,backend,skip_build=False):
    print('='*92); print('VERIFY SAMPLING / GEOMETRY LAB V0.1.1'); print('='*92); failures=0
    checks=[('Frontend route',APP_IMPORT in (frontend/'src/App.tsx').read_text() and APP_ROUTE in (frontend/'src/App.tsx').read_text()),('Backend route',ROUTER_IMPORT in (backend/'app/api/v1/api.py').read_text() and ROUTER_MOUNT in (backend/'app/api/v1/api.py').read_text()),('Launcher enabled',"route: '/labs/sampling-geometry'" in (frontend/'src/Pages/LabView.tsx').read_text()),('Three workspaces',all(x in (frontend/'src/Pages/SamplingGeometryLabPage.tsx').read_text() for x in ['Geometry','Spatial Sampling','Spectral / Statistics'])),('Guide UI','OPERATOR GUIDE / INTERACTIVE MODEL' in (frontend/'src/components/VisionLabs/SamplingGeometry/SamplingGuideModal.tsx').read_text()),('Upstream Lab Service binding','from-lab-service' in (backend/'app/api/v1/endpoints/sampling_geometry_api.py').read_text()),('Sampling service adapter','sampling_geometry' in (backend/'app/services/vision_labs/service/runtime.py').read_text()),('LLM update note',(frontend/'docs/llm_context/updates/v0100_sampling_geometry_lab.md').exists())]
    for label,ok in checks: print(f"[{'OK' if ok else 'FAIL'}] {label}"); failures += 0 if ok else 1
    for v in list(CREATE_FILES)+list(NEW_FILES):
        if v.startswith('backend/') and v.endswith('.py'):
            try: py_compile.compile(str(actual(frontend,backend,v)),doraise=True)
            except Exception as e: print('[FAIL] Python syntax',v,e); failures+=1
    s=backend_smoke(backend)
    if s.returncode==0: print('[OK] Backend runtime/service smoke'); print(s.stdout.strip())
    else: print('[FAIL] Backend smoke'); print((s.stdout+'\n'+s.stderr).strip()); failures+=1
    test=backend/'tests/vision_labs/sampling_geometry/test_sampling_geometry_lab_v0100.py'
    if importlib.util.find_spec('pytest') is not None:
        r=subprocess.run([sys.executable,'-m','pytest','-q',str(test.relative_to(backend))],cwd=str(backend),text=True,capture_output=True)
        if r.returncode==0: print('[OK] Regression tests'); print(r.stdout.strip())
        else: print('[FAIL] Regression tests'); print((r.stdout+'\n'+r.stderr).strip()); failures+=1
    else: print('[SKIP] pytest not installed')
    t=ts_check(frontend)
    if t.returncode==0: print('[OK] TypeScript syntax/transpile')
    else: print('[FAIL] TypeScript syntax'); print((t.stdout+'\n'+t.stderr).strip()); failures+=1
    if not skip_build and (frontend/'node_modules').exists() and (frontend/'package.json').exists():
        r=subprocess.run(['npm','run','build'],cwd=str(frontend)); failures += 0 if r.returncode==0 else 1
    else: print('[SKIP] Frontend npm build')
    if failures: print(f'[FAIL] {failures} verification issue(s)'); return 1
    print('[OK] Sampling / Geometry LAB v0.1.1 verified.'); return 0

def main():
    p=argparse.ArgumentParser(); p.add_argument('command',choices=['scan','apply','verify']); p.add_argument('--frontend'); p.add_argument('--backend'); p.add_argument('--skip-build',action='store_true'); a=p.parse_args()
    try:
        f,b=resolve_roots(a.frontend,a.backend)
        return scan(f,b) if a.command=='scan' else apply(f,b) if a.command=='apply' else verify(f,b,a.skip_build)
    except Exception as e: print('[ERROR]',e); return 2
if __name__=='__main__': raise SystemExit(main())
